mapper.update:
UPDATE tb_outbox_event
SET
    status = 'PROCESSING',
    locked_by = #{lockedBy},
    locked_until = #{lockedUntil},
    update_time = CURRENT_TIMESTAMP(3)
WHERE id = #{id}
  AND (
    (
        status = 'PENDING'
            AND next_retry_time <= #{now}
        )
        OR
    (
        status = 'PROCESSING'
            AND locked_until IS NOT NULL
            AND locked_until <= #{now}
        )
    )

mapper.select:
SELECT
id, event_id, event_type, aggregate_type, aggregate_id,
status, retry_count, next_retry_time, locked_by, locked_until,
last_error, replay_count, last_replay_by, last_replay_time,
create_time, update_time, sent_time
FROM tb_outbox_event


        AND event_id = #{query.eventId}


        AND event_type = #{query.eventType}


        AND aggregate_type = #{query.aggregateType}


        AND aggregate_id = #{query.aggregateId}


        AND status = #{query.status}


        AND create_time >= #{query.createTimeStart}


        AND create_time <= #{query.createTimeEnd}


ORDER BY create_time DESC, id DESC
